struct MissingEncodingGuard { output_bytes: usize }
struct MissingControlledEncoding { output_bytes: usize }
struct GuardedEncoding { output_bytes: usize }
struct EstimatedEncoding { output_bytes: usize }
std::thread_local! { static ENCODER_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) }; static CONTROLLED_ENCODER_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) }; }

macro_rules! expansion_owner {
    ($owner:ty, $($guard:item)*) => {
        impl ArtifactDsl for $owner {
            const EXTENSION: &'static str = "expansion";
            fn parse_dsl(text: &str) -> Result<Self, TextError> { Ok(Self { output_bytes: text.len() }) }
            fn print_dsl(&self) -> String { ENCODER_CALLS.with(|count| count.set(count.get() + 1)); "x".repeat(self.output_bytes) }
        }
        impl ArtifactPack for $owner {
            fn encode_pack_with(&self, _: &PackEncodeOptions) -> Result<Vec<u8>, PackError> { ENCODER_CALLS.with(|count| count.set(count.get() + 1)); Ok(vec![120; self.output_bytes]) }
            fn decode_pack_with(bytes: &[u8], _: &PackDecodeOptions) -> Result<Self, PackError> { Ok(Self { output_bytes: bytes.len() }) }
        }
        impl ArtifactSqliteSnapshot for $owner {
            const SQLITE_SCHEMA: &'static str = include_str!("../🧬️schema/🗄️.sql");
            fn to_sqlite_database(&self, control: &mut SqliteSnapshotControl<'_>) -> Result<SqliteDatabase,ValueError> {
                control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, 0, 1)?;
                let mut database = SqliteDatabase::from_schema(Self::SQLITE_SCHEMA)?;
                database.table_mut("encoding_expansion")?.rows.push(SqliteRow { rowid: 1, values: vec![SqliteValue::Integer(1), SqliteValue::Integer(i64::try_from(self.output_bytes).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"output size exceeds i64"))?)] });
                Ok(database)
            }
            fn from_sqlite_database(database: &SqliteDatabase, control: &mut SqliteSnapshotControl<'_>) -> Result<Self,ValueError> {
                control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, 1)?;
                Ok(Self { output_bytes: usize::try_from(database.table("encoding_expansion")?.rows[0].integer(1)?).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"stored output size must fit usize"))? })
            }
            $($guard)*
        }
    };
}
expansion_owner!(MissingEncodingGuard,);
expansion_owner!(MissingControlledEncoding,
    fn preflight_sqlite_snapshot_encoding(&self, _: SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<(),ValueError> {
        let mut bound=NativeEncodingBound::new(control)?;bound.add(self.output_bytes)?;bound.finish()
    }
);
expansion_owner!(GuardedEncoding,
    fn encode_sqlite_snapshot_native(&self, encoding: SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<crate::io_schema::IoPayload,ValueError> {
        use semio_framework_value::native_encoding::{NativeEncodeControl, NativeEncodeProgress};
        let limits=control.limits();if self.output_bytes>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"native fixture exceeds file ceiling"))}let mut callback=|event:NativeEncodeProgress|control.checkpoint(SqliteSnapshotPhase::EncodeNative,event.completed,event.total).is_ok();let mut native=NativeEncodeControl::new(limits.max_value_bytes,&mut callback);native.begin_stage(self.output_bytes)?;let mut bytes=native.allocate_vec(self.output_bytes)?;CONTROLLED_ENCODER_CALLS.with(|count|count.set(count.get()+1));while bytes.len()<self.output_bytes{let count=65536.min(self.output_bytes-bytes.len());bytes.resize(bytes.len()+count,b'x');native.advance(count)?;}match encoding{SnapshotEncoding::Binary=>Ok(crate::io_schema::IoPayload::Binary(bytes)),SnapshotEncoding::Text=>Ok(crate::io_schema::IoPayload::Text(String::from_utf8(bytes).map_err(|_|ValueError::new(ValueRefusalKind::InvariantViolated,"generated fixture text must be UTF-8"))?))}
    }
    fn preflight_sqlite_snapshot_encoding(&self, _: SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<(),ValueError> {
        let mut bound = NativeEncodingBound::new(control)?;
        bound.add(self.output_bytes)?;
        bound.finish()
    }
);
expansion_owner!(EstimatedEncoding,
    fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<crate::io_schema::IoPayload,ValueError>{GuardedEncoding{output_bytes:self.output_bytes}.encode_sqlite_snapshot_native(encoding,control)}
    fn preflight_sqlite_snapshot_encoding(&self,_:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
        let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut bound=NativeEncodingBound::new(control)?;bound.repeated(self.output_bytes,fixture["exactEncodingAdmission"]["estimateMultiplier"].as_u64().unwrap()as usize)?;bound.finish()
    }
);

#[test]
fn sqlite_snapshot_native_exact_output_admission_ignores_approximate_preflight(){
    use std::{io::Write,process::{Command,Stdio}};
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../🧬️schema/🔣️.json")).unwrap();let case=&fixture["exactEncodingAdmission"];let output_bytes=case["outputBytes"].as_u64().unwrap()as usize;let snapshot=EstimatedEncoding{output_bytes};let mut limits=SqliteDatabaseLimits::default();limits.max_value_bytes=case["maximumBytes"].as_u64().unwrap()as usize;limits.max_file_bytes=case["maximumFileBytes"].as_u64().unwrap()as usize;let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=crate::sqlite_snapshot::export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
    let script="import Ajv from'ajv';import{Database}from'bun:sqlite';const x=JSON.parse(await Bun.stdin.text());if(!new Ajv({strict:true}).validate(x.schema,x.fixture))throw Error('fixture');const d=Database.deserialize(Buffer.from(x.bytes,'base64'));const n=d.query('SELECT output_bytes FROM encoding_expansion WHERE id=1').get().output_bytes;await Bun.write(Bun.stdout,Uint8Array.from({length:n},()=>120));d.close();";let input=serde_json::json!({"fixture":fixture,"schema":schema,"bytes":protocol::bytes::encode_base64(&bytes)});let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(input.to_string().as_bytes()).unwrap();let oracle=child.wait_with_output().unwrap();assert!(oracle.status.success(),"{}",String::from_utf8_lossy(&oracle.stderr));assert_eq!(oracle.stdout.len(),output_bytes);
    let dialect=crate::io_schema::ArtifactDialect{artifact_kind:"fixture.expansion".into(),standard:"1".into(),subset:"*".into()};
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());ENCODER_CALLS.with(|count|count.set(0));let result=(EstimatedEncoding::sqlite_codec().import)("fixture.expansion/v1",&dialect,database.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let actual=match result.value{crate::io_schema::IoPayload::Binary(bytes)=>bytes,crate::io_schema::IoPayload::Text(text)=>text.into_bytes()};assert_eq!(actual,oracle.stdout);ENCODER_CALLS.with(|count|assert_eq!(count.get(),0));let mut short=limits;short.max_file_bytes-=1;assert!((EstimatedEncoding::sqlite_codec().import)("fixture.expansion/v1",&dialect,database.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());
    }
}

#[test]
fn sqlite_snapshot_native_encoding_admission_rejects_before_either_encoder() {
    use std::{io::Write, process::{Command, Stdio}};
    let fixture: serde_json::Value = serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    let dialect = crate::io_schema::ArtifactDialect { artifact_kind: "fixture.expansion".into(), standard: "1".into(), subset: "*".into() };
    for case in fixture["cases"].as_array().unwrap() {
        let output_bytes = case["outputBytes"].as_u64().unwrap() as usize;
        let guarded = case["guarded"].as_bool().unwrap();
        let codec = if !guarded { MissingEncodingGuard::sqlite_codec() } else if case["controlled"].as_bool().unwrap() { GuardedEncoding::sqlite_codec() } else { MissingControlledEncoding::sqlite_codec() };
        let database = GuardedEncoding { output_bytes }.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_| true, SqliteDatabaseLimits::default())).unwrap();
        let bytes = crate::sqlite_snapshot::export_sqlite_database(&database, SqliteDatabaseLimits::default(), &mut |_| true).unwrap();
        let script = "import {Database} from 'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok')throw Error('integrity');await Bun.write(Bun.stdout,String(db.query('SELECT output_bytes FROM encoding_expansion WHERE id=1').get().output_bytes));db.close();";
        let mut child = Command::new("bun").args(["-e", script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
        child.stdin.take().unwrap().write_all(&bytes).unwrap();
        let result = child.wait_with_output().unwrap();
        assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
        assert_eq!(String::from_utf8(result.stdout).unwrap(), output_bytes.to_string());
        for encoding in [SnapshotEncoding::Binary, SnapshotEncoding::Text] {
            ENCODER_CALLS.with(|count| count.set(0));
            CONTROLLED_ENCODER_CALLS.with(|count| count.set(0));
            let mut limits = SqliteDatabaseLimits::default();
            limits.max_value_bytes = case["maximumBytes"].as_u64().unwrap() as usize;
            limits.max_file_bytes = limits.max_value_bytes;
            let cancel = case["cancelEncoding"].as_bool().unwrap();
            let mut callback = |event: crate::sqlite_snapshot::SqliteSnapshotProgress| !cancel || event.phase != SqliteSnapshotPhase::EncodeNative;
            let result = (codec.import)("fixture.expansion/v1", &dialect, database.clone(), encoding, &mut SqliteSnapshotControl::new(&mut callback, limits));
            let encoded = case["encoded"].as_bool().unwrap();
            assert_eq!(result.is_ok(), encoded, "{} {encoding:?}: {result:?}", case["id"]);
            ENCODER_CALLS.with(|count| assert_eq!(count.get(), 0, "ordinary encoders must never be used by SQLite import"));
            CONTROLLED_ENCODER_CALLS.with(|count| assert_eq!(count.get(), usize::from(encoded)));
            if let Ok(outcome) = result { let actual = match outcome.value { crate::io_schema::IoPayload::Binary(bytes) => bytes.len(), crate::io_schema::IoPayload::Text(text) => text.len() }; assert_eq!(actual, output_bytes); }
        }
    }
}

fn encoding_stops_inside_owned_output(encoding:SnapshotEncoding){
    use std::{io::Write,process::{Command,Stdio}};
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../🧬️schema/🔣️.json")).unwrap();let case=&fixture["interiorEncoding"];
    let output_bytes=case["outputBytes"].as_u64().unwrap()as usize;let cancel_at=case["cancelAt"].as_u64().unwrap()as usize;
    let snapshot=GuardedEncoding{output_bytes};let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=crate::sqlite_snapshot::export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
    let input=serde_json::json!({"fixture":fixture,"schema":schema,"bytes":protocol::bytes::encode_base64(&bytes)});
    let script="import Ajv from 'ajv';import{Database}from'bun:sqlite';const x=JSON.parse(await Bun.stdin.text());if(!new Ajv({strict:true}).validate(x.schema,x.fixture))throw Error('fixture');const db=Database.deserialize(Buffer.from(x.bytes,'base64'));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok')throw Error('integrity');await Bun.write(Bun.stdout,String(db.query('SELECT output_bytes FROM encoding_expansion WHERE id=1').get().output_bytes));db.close();";
    let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(input.to_string().as_bytes()).unwrap();let oracle=child.wait_with_output().unwrap();assert!(oracle.status.success(),"{}",String::from_utf8_lossy(&oracle.stderr));assert_eq!(String::from_utf8(oracle.stdout).unwrap(),output_bytes.to_string());
    let dialect=crate::io_schema::ArtifactDialect{artifact_kind:"fixture.expansion".into(),standard:"1".into(),subset:"*".into()};let mut limits=SqliteDatabaseLimits::default();limits.max_value_bytes=case["maximumBytes"].as_u64().unwrap()as usize;limits.max_file_bytes=limits.max_value_bytes;
    let mut reached=false;ENCODER_CALLS.with(|count|count.set(0));let mut callback=|event:crate::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.total==output_bytes&&event.completed>=cancel_at&&event.completed<event.total{reached=true;false}else{true}};
    let result=(GuardedEncoding::sqlite_codec().import)("fixture.expansion/v1",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut callback,limits));
    assert_eq!(result.is_err(),case["expectedCanceled"].as_bool().unwrap(),"{encoding:?} encoding must stop during real output ownership");assert!(reached,"expected an interior EncodeNative byte checkpoint");ENCODER_CALLS.with(|count|assert_eq!(count.get(),0,"ordinary printer/packer must not be called"));
}
#[test]
fn sqlite_snapshot_native_binary_encoding_stops_inside_owned_output(){encoding_stops_inside_owned_output(SnapshotEncoding::Binary)}
#[test]
fn sqlite_snapshot_native_text_encoding_stops_inside_owned_output(){encoding_stops_inside_owned_output(SnapshotEncoding::Text)}

#[derive(dsl::DslRecord)]
struct ControlledOutputFields{items:Vec<String>}

#[test]
fn sqlite_snapshot_native_record_owner_output_uses_one_control_through_both_envelopes(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let case=&fixture["typedProjection"];let count=case["count"].as_u64().unwrap()as usize;let source=ControlledOutputFields{items:(0..count).map(|index|index.to_string()).collect()};let limits=SqliteDatabaseLimits::default();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let output=super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let decoded=super::decode_sqlite_snapshot_record_native(&output,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|record,native|ControlledOutputFields::__dsl_from_record_controlled(record,native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(decoded.items,source.items);
        let length=match &output{crate::io_schema::IoPayload::Binary(bytes)=>bytes.len(),crate::io_schema::IoPayload::Text(text)=>text.len()};let mut exact=limits;exact.max_file_bytes=length;assert_eq!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),output);exact.max_file_bytes-=1;assert!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),&mut SqliteSnapshotControl::new(&mut |_|true,exact)).is_err());
        let mut reached=false;let mut callback=|event:crate::sqlite_snapshot::SqliteSnapshotProgress|if event.phase==SqliteSnapshotPhase::EncodeNative&&event.total==count&&event.completed>=256&&event.completed<event.total{reached=true;false}else{true};assert!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err());assert!(reached);
        let mut tiny=limits;tiny.max_allocation_bytes=1;assert!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),&mut SqliteSnapshotControl::new(&mut |_|true,tiny)).is_err());
    }
}

#[test]
fn sqlite_snapshot_native_typed_projection_stops_inside_known_collection_before_ordinary_copy(){
    use semio_framework_value::native_encoding::{NativeEncodeControl,NativeEncodeProgress};
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let case=&fixture["typedProjection"];let count=case["count"].as_u64().unwrap()as usize;let cancel_at=case["cancelAt"].as_u64().unwrap()as usize;
    let source=ControlledOutputFields{items:(0..count).map(|index|index.to_string()).collect()};let mut interior=false;
    let mut callback=|event:NativeEncodeProgress|{if event.total==count&&event.completed>=cancel_at&&event.completed<event.total{interior=true;false}else{true}};let mut control=NativeEncodeControl::new(case["maximumBytes"].as_u64().unwrap()as usize,&mut callback);
    assert!(source.__dsl_to_record_controlled(&mut control).is_err());assert!(interior);
    let mut admit=|_|true;let mut control=NativeEncodeControl::new(1,&mut admit);assert!(source.__dsl_to_record_controlled(&mut control).is_err());assert_eq!(control.owned_bytes(),0);
    let record=source.__dsl_to_record_controlled(&mut NativeEncodeControl::new(case["maximumBytes"].as_u64().unwrap()as usize,&mut |_|true)).unwrap();let actual=ControlledOutputFields::__dsl_from_record(&record).unwrap();assert_eq!(actual.items,source.items);
    use std::{io::Write,process::{Command,Stdio}};let script="import{Database}from'bun:sqlite';const x=JSON.parse(await Bun.stdin.text());const d=new Database(':memory:');d.run('CREATE TABLE item(id INTEGER PRIMARY KEY,text TEXT NOT NULL)');for(let i=0;i<x.count;i++)d.run('INSERT INTO item VALUES(?,?)',i,String(i));await Bun.write(Bun.stdout,JSON.stringify(d.query('SELECT text FROM item ORDER BY id').all().map(r=>r.text)));d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(case.to_string().as_bytes()).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(actual.items,serde_json::from_slice::<Vec<String>>(&output.stdout).unwrap());
}

