#[test]
fn sqlite_snapshot_native_physical_text_keeps_literal_lexer_boundaries(){
    use semio_framework_value::native_encoding::NativeEncodeControl;
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    let spec=RecordSpec::new(Some("literal"),RecordLayout::Inline,vec![FieldSpec::new(0,"text",Shape::Text)]);
    for source in fixture["physicalLiteralTexts"].as_array().unwrap(){
        let mut record=RecordValue::default();record.fields.insert(0,FieldValue::Text(source.as_str().unwrap().into()));
        for mode in [JoinMode::Document,JoinMode::Inline]{
            let mut accept=|_|true;let mut control=NativeEncodeControl::new(65536,&mut accept);
            let text=crate::os_dsl::schema::print_controlled(&record,&spec,mode,usize::MAX,&mut control).unwrap();
            assert_eq!(text,crate::os_dsl::schema::print(&record,&spec,mode),"{source}");
            assert_eq!(crate::os_dsl::schema::parse_exact(&text,&spec,&ParseOptions::default()).unwrap(),record,"{source}");
            let mut accept=|_|true;let mut control=NativeDecodeControl::new(65536,&mut accept);
