    let registry = ArtifactEnvelopeFieldDecoderRegistry::<(), ()>::new();
    let first = registry.try_admit(Box::new(TestEnvelopeFieldDecoder { terminal: true, accepted: 0 })).unwrap_or_else(|_| panic!("first exact decoder lease"));
