        id: "group-reader".into(),
        vcs: ArtifactVcs { initial_snapshot: snapshot, edits, changes: ArtifactHistoryLedger::new(), checkpoints: ArtifactHistoryLedger::new(), alternatives: ArtifactHistoryLedger::new() },
        backbone: None,
